-- ETERNA v159 · SEMILLA CURRICULAR DE PRUEBA
-- NO sustituye el corpus estatal/autonómico completo. Sirve para validar retrieval + tutor + verificador.
-- Requiere haber ejecutado supabase-eterna-v159.sql.
with src as (select id,stage from public.eterna_curriculum_sources where jurisdiction='ES-STATE')
on conflict(jurisdiction,school_year,subject,concept_code) do update set summary=excluded.summary,updated_at=now();
